/**
 * frontend/src/components/CameraRecognition.jsx
 * Version finale - Webcam intégrée du PC + reconnaissance faciale en temps réel
 */

import React, { useRef, useState, useEffect } from "react";
import axios from "axios";

const CameraRecognition = () => {
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const [error, setError] = useState(null);
  const [results, setResults] = useState([]);
  const [autoMode, setAutoMode] = useState(false);
  const [successCount, setSuccessCount] = useState(0);
  const [failCount, setFailCount] = useState(0);
  let captureInterval = useRef(null);

  // ================= INIT CAMERA =================
  const initCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: "user" } // force la caméra intégrée du PC
      });
      videoRef.current.srcObject = stream;
      setError(null);
      console.log("[INFO] Caméra intégrée démarrée");
    } catch (err) {
      setError("Impossible d'accéder à la caméra du PC : " + err.message);
      console.error("[ERROR] getUserMedia:", err);
    }
  };

  useEffect(() => {
    initCamera();
    return () => stopCamera();
  }, []);

  // ================= CAPTURE FRAME =================
  const captureFrame = async () => {
    if (!videoRef.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);

    const imageData = canvas.toDataURL("image/jpeg");

    try {
      const res = await axios.post("/attendance/recognize/", {
        image: imageData
      });

      if (res.data?.success) {
        setResults(prev => [res.data, ...prev]);
        setSuccessCount(c => c + 1);
        console.log("[INFO] Reconnaissance réussie:", res.data);
      } else {
        setFailCount(c => c + 1);
        console.warn("[INFO] Visage non reconnu");
      }
    } catch (err) {
      setError("Erreur serveur, veuillez réessayer");
      console.error("[ERROR] Backend:", err);
    }
  };

  // ================= AUTO MODE =================
  const startAuto = () => {
    if (captureInterval.current) return;
    setAutoMode(true);
    captureInterval.current = setInterval(captureFrame, 3000); // toutes les 3s
    console.log("[INFO] Mode auto activé");
  };

  const stopAuto = () => {
    clearInterval(captureInterval.current);
    captureInterval.current = null;
    setAutoMode(false);
    console.log("[INFO] Mode auto arrêté");
  };

  // ================= STOP CAMERA =================
  const stopCamera = () => {
    if (videoRef.current?.srcObject) {
      videoRef.current.srcObject.getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
      console.log("[INFO] Caméra arrêtée");
    }
  };

  // ================= RENDER =================
  return (
    <div style={{ textAlign: "center" }}>
      <h2>🎥 Reconnaissance faciale en temps réel</h2>

      {error && <p style={{ color: "red" }}>{error}</p>}

      <video
        ref={videoRef}
        autoPlay
        playsInline
        style={{ width: "640px", border: "2px solid #4F46E5", borderRadius: "12px" }}
      />
      <canvas ref={canvasRef} width="640" height="480" style={{ display: "none" }} />

      <div style={{ marginTop: "20px" }}>
        <button onClick={captureFrame}>📸 Capturer maintenant</button>
        {!autoMode ? (
          <button onClick={startAuto}>▶️ Démarrer Auto</button>
        ) : (
          <button onClick={stopAuto}>⏹ Arrêter Auto</button>
        )}
        <button onClick={stopCamera}>🛑 Fermer Caméra</button>
      </div>

      <div style={{ marginTop: "20px" }}>
        <p>Succès : {successCount} • Échecs : {failCount}</p>
      </div>

      <div style={{ marginTop: "20px", textAlign: "left" }}>
        <h3>Résultats récents :</h3>
        {results.length === 0 ? (
          <p>Aucun résultat pour l’instant.</p>
        ) : (
          results.slice(0, 5).map((r, i) => (
            <div
              key={i}
              style={{
                padding: "10px",
                marginBottom: "8px",
                borderRadius: "8px",
                backgroundColor: r.success ? "#DCFCE7" : "#FEE2E2",
                border: r.success ? "1px solid #10B981" : "1px solid #EF4444"
              }}
            >
              {r.success ? (
                <p>
                  Étudiant : {r.name} ({r.email}) • Confiance : {(r.confidence * 100).toFixed(1)}% • Heure : {r.timestamp}
                </p>
              ) : (
                <p>Visage non reconnu</p>
              )}
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default CameraRecognition;
